r","Josh"]},{"t":"Receive feedback from the Shipping team and make adjustments as needed","s":"Not started","n":"Adjustments to be made by Vital AI","w":["Mat Potter","Lindsay","Bryce","Josh","Josh C."]},{"t":"Confirm barcode system is good to go","s":"Not started","n":"May have concerns the system is clunky and might cause barriers for the shipping team - TBD","w":["Avery","Bryce","Josh"]},{"t":"Work with vendors to create/produce barcodes on our incoming inventory (boxes)","s":"Not started","w":["Ouri"]}]},{"c":"POA-01","name":"Production order automation","sum":"Extract order data from QuickBooks so production orders build themselves.","st":"Not started","pr":"Urgent","tg":"2026-10-23","col":"#7A4FD0","tasks":[{"t":"Work on extracting data from QB","s":"Not started","o":"Paul (Vital AI)","n":"How can we flag an update in the order after is has been uploaded?"},{"t":"Ask Project Coordinators/Avery how often our orders \"change\"","s":"Not started","o":"Project Coordinators","n":"How frequent do we see these changes reflects how in depth/complex our process for change look like?","w":["Avery"]},{"t":"Look at ZedAxis for extraction","s":"Not started"}]}]}$json$::jsonb as j;
with ppl as (
  insert into public.init_people (display_name, email, user_id)
  select x->>'n', x->>'e', (select id from auth.users u where u.email = x->>'l')
  from init_seed src, jsonb_array_elements(j->'people') x
  where not exists (select 1 from public.init_people pe where lower(pe.display_name) = lower(x->>'n'))
  returning id
)
select count(*) as people_added from ppl;

insert into public.init_projects (code, name, summary, stage, priority, target_date, color, sort_order)
select x->>'c', x->>'name', x->>'sum', x->>'st', x->>'pr', (x->>'tg')::date, x->>'col', o
from init_seed src, jsonb_array_elements(j->'projects') with ordinality as e(x, o)
where not exists (select 1 from public.init_projects p where p.code = x->>'c');

insert into public.init_tasks (project_id, position, title, status, due_date, others, latest_note, latest_note_at)
select p.id, o, t->>'t', t->>'s', (t->>'d')::date, t->>'o', t->>'n',
       case when t ? 'na' then ((t->>'na') || ' 12:00-08')::timestamptz end
from init_seed src, jsonb_array_elements(j->'projects') pr
join public.init_projects p on p.code = pr->>'c'
cross join lateral jsonb_array_elements(pr->'tasks') with ordinality as e(t, o)
where not exists (select 1 from public.init_tasks x where x.project_id = p.id and x.position = o);

insert into public.init_task_assignees (task_id, person_id)
select tk.id, pe.id
from init_seed src, jsonb_array_elements(j->'projects') pr
join public.init_projects p on p.code = pr->>'c'
cross join lateral jsonb_array_elements(pr->'tasks') with ordinality as e(t, o)
join public.init_tasks tk on tk.project_id = p.id and tk.position = o
cross join lateral jsonb_array_elements_text(coalesce(t->'w', '[]')) w
join public.init_people pe on lower(pe.display_name) = lower(w) and pe.active
on conflict do nothing;

-- Imported Done tasks finished before the import, not today: date them to the tracker snapshot so
-- "done this week" and "moved this week" only count real work done in the tracker.
update public.init_tasks t set completed_at = '2026-10-30 17:00-07', status_changed_at = '2026-10-30 17:00-07'
from public.init_projects p
where p.id = t.project_id and t.created_by = 'import: Lindsay''s tracker (Oct 30)';
commit;
